#!/usr/bin/env python3
"""Phase 4E: standard-library-only, evaluator-side frozen-artifact analysis.

No production modules are imported. The only repository writes are the three
new Phase 4E outputs. Existing outputs are never overwritten.
"""
import collections
import hashlib
import json
import math
import re
import statistics
from pathlib import Path

ROOT = Path('/home/minhkha/kk/TTTN/legal-agentic-rag')
BASE = ROOT / 'data/evaluation/generation'
EPS = 1e-9
METRICS = ['answer_completeness', 'citation_completeness', 'citation_correctness', 'groundedness', 'unsupported_claim_rate']
PROFILES = {'none': 'P0 — No Substantive Intervention', 'expansion_only': 'P1 — Evidence Expansion Only', 'answer_revision_only': 'P2 — Answer Revision Only', 'citation_revision_only': 'P3 — Citation Revision Only', 'multiple': 'P4 — Multiple Interventions'}
OUTCOMES = {'improved': 'O1 — Improved', 'improved_with_tradeoff': 'O2 — Improved with Trade-off', 'no_change': 'O3 — No Change', 'regressed': 'O4 — Regressed', 'inconclusive': 'O5 — Inconclusive'}
OBSERVATIONS = dict(zip(OUTCOMES, ['observed_gain', 'observed_tradeoff', 'no_observed_gain', 'observed_regression', 'inconclusive']))
BUDGETS = {'max_retrieval_expansions': 1, 'max_sub_queries': 3, 'max_answer_revisions': 1, 'max_citation_revisions': 1, 'max_llm_calls': 6}
CONFIG = {'bm25': 'BM25-simple-v0', 'bm25_depth': 20, 'dense': 'dense-jina-v3-v0', 'dense_depth': 20, 'candidate_merge': 'union_deduplicate_by_chunk_id', 'fusion': None, 'reranker': 'BAAI/bge-reranker-v2-m3', 'top_k': 5}
STAGES = {'coverage_check', 'answer_generation', 'completeness_check', 'answer_revision', 'citation_revision', 'semantic_citation_alignment'}

def require(condition, message):
    if not condition:
        raise ValueError(message)

def close(a, b):
    return a is not None and b is not None and abs(a-b) <= EPS

def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))

def read_lines(path):
    return [json.loads(line) for line in Path(path).read_text(encoding='utf-8').splitlines() if line.strip()]

def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def index_unique(rows, label):
    result = {}
    for row in rows:
        q = row['query_id']
        require(q not in result, f'{label}: duplicate query ID {q}')
        result[q] = row
    return result

def align(reference, other, label):
    require(set(reference) == set(other), f'{label}: missing/extra query IDs: {sorted(set(reference)^set(other))}')
    for q in reference:
        require(reference[q]['query'] == other[q]['query'], f'{label}: mismatched query text {q}')

def validate_trace_links(agentic, traces):
    require(set(agentic) == set(traces), 'missing/extra trace')
    for q, row in agentic.items():
        t = traces[q]
        require(t['run_id'] == f'agentic-v1-{q}', f'mismatched trace query ID {q}')
        require(t['query'] == row['query'], f'mismatched trace query text {q}')
        require(t == row['trace'], f'embedded/disk trace mismatch {q}')

def profile(expansion, answer, citation):
    flags = [expansion, answer, citation]
    require(all(isinstance(x, bool) for x in flags), 'intervention flags must be boolean')
    if sum(flags) >= 2:
        return 'multiple'
    return next((p for f, p in zip(flags, ['expansion_only', 'answer_revision_only', 'citation_revision_only']) if f), 'none')

def oriented_deltas(standard, agentic):
    return {m: None if standard.get(m) is None or agentic.get(m) is None else
            (standard[m]-agentic[m] if m == 'unsupported_claim_rate' else agentic[m]-standard[m]) for m in METRICS}

def outcome(deltas):
    if any(x is None or not math.isfinite(x) for x in deltas.values()) or set(deltas) != set(METRICS):
        return 'inconclusive'
    up = any(x > EPS for x in deltas.values())
    down = any(x < -EPS for x in deltas.values())
    return 'improved_with_tradeoff' if up and down else 'improved' if up else 'regressed' if down else 'no_change'

def point_changes(standard, agentic):
    return sorted(set(agentic)-set(standard)), sorted(set(standard)-set(agentic))

def production_calls(trace):
    calls = trace['llm_calls']
    require(all(c['stage'] in STAGES for c in calls), 'ambiguous or non-production LLM call stage')
    require([c['call_number'] for c in calls] == list(range(1, len(calls)+1)), 'LLM call numbering mismatch')
    require(len(calls) == trace['llm_call_count'], 'LLM count mismatch')
    return len(calls)

def calibrate(complete, benchmark, status):
    require(isinstance(complete, bool), 'missing internal completeness decision')
    bc = close(benchmark, 1)
    key = ('internal_complete' if complete else 'internal_incomplete') + ('_and_benchmark_complete' if complete and bc else '_but_benchmark_incomplete' if complete else '_but_benchmark_complete' if bc else '_and_benchmark_incomplete')
    return key, status == 'success' and not bc

def count_all(values, keys):
    c = collections.Counter(values)
    return {k: c[k] for k in keys}

def stats(values):
    if not values:
        return {'mean': None, 'median': None, 'max': None, 'total': 0, 'distribution': {}}
    return {'mean': statistics.mean(values), 'median': statistics.median(values), 'max': max(values), 'total': sum(values), 'distribution': dict(sorted(collections.Counter(values).items()))}

def citations(answer):
    return list(dict.fromkeys(re.findall(r'\bE\d+\b', answer)))

def lexical_body(answer):
    return ' '.join(re.sub(r'\[E\d+\]', '', answer).split())

def evidence_signature(evidence):
    # Compare content and the citation map, without irrelevant runtime audit metadata.
    return [(e['evidence_id'], e['chunk_id'], e['text'], e['retrieval_text']) for e in evidence]

def check_before_hashes():
    hashes = read('/tmp/phase4e_source_hashes.json')
    for path, expected in hashes.items():
        require(digest(ROOT/path) == expected, f'Source changed: {path}')
    return hashes

def validate_and_load():
    before = check_before_hashes()
    am = read(BASE/'agentic_rag_metrics_v1_agentic-v1.json')
    sm = read(BASE/'standard_rag_manifest_v0.json')
    gm = read(BASE/'generation_eval_v1_verified_manifest.json')
    fm = read(BASE/'failure_analysis_metrics_v0.json')
    gold_payload = read(ROOT/fm['inputs']['generation_ground_truth'])
    gold = index_unique(gold_payload['items'], 'gold')
    standard = index_unique(read_lines(ROOT/fm['inputs']['standard_rag_result']), 'Standard RAG')
    agentic = index_unique(read_lines(BASE/'agentic_rag_eval_v1_agentic-v1.jsonl'), 'Agentic RAG v1')
    failures = index_unique(read(BASE/'failure_analysis_queries_v0.json')['queries'], 'Phase 4A')
    points = read_lines(BASE/'failure_analysis_points_v0.jsonl')
    retrieval = index_unique(read_lines(ROOT/fm['inputs']['retrieval_benchmark']), 'retrieval evaluation')
    standard_metrics = read(BASE/'standard_rag_metrics_v0.json')
    for name, rows in [('gold',gold),('Standard',standard),('Agentic',agentic),('Phase 4A', failures),('retrieval',retrieval)]:
        require(len(rows) == 31, f'{name} count !=31')
        align(gold, rows, name)
    require(gold_payload['evaluation_version'] == sm['generation_evaluation_version'] == gm['evaluation_version'] == 'generation-eval-v1', 'dataset version mismatch')
    require(gold_payload['dataset_status'] == gm['dataset_status'] == sm['generation_dataset_status'] == 'verified', 'dataset not verified')
    require(sum(len(g['required_points']) for g in gold.values()) == 102, 'required point count !=102')
    point_index = {}
    for p in points:
        key = p['query_id'], p['point_id']
        require(key not in point_index, f'duplicate Phase 4A point {key}')
        point_index[key] = p
    expected_points = {(q,p['point_id']) for q,g in gold.items() for p in g['required_points']}
    require(len(expected_points) == 102 and set(point_index) == expected_points, 'Phase 4A/gold point mismatch')
    paths = {'generation_verified_sha256': fm['inputs']['generation_ground_truth'], 'retrieval_eval_sha256': fm['inputs']['retrieval_benchmark'], 'corpus_chunks_sha256': fm['inputs']['corpus'], 'results_sha256': 'data/evaluation/generation/agentic_rag_eval_v1_agentic-v1.jsonl', 'standard_rag_metrics_sha256': 'data/evaluation/generation/standard_rag_metrics_v0.json', 'prompt_sha256': 'prompts/legal_rag_v0.txt'}
    for key,path in paths.items():
        require(before[path] == am['manifest']['dataset_hashes'][key], f'Agentic manifest hash mismatch {key}')
        if key in sm['dataset_hashes']:
            require(before[path] == sm['dataset_hashes'][key], f'Standard manifest hash mismatch {key}')
        if key in fm['input_hashes']:
            require(before[path] == fm['input_hashes'][key], f'Phase 4A hash mismatch {key}')
    for key,path in [('result_dataset_sha256',fm['inputs']['standard_rag_result']),('generation_verified_manifest_sha256','data/evaluation/generation/generation_eval_v1_verified_manifest.json')]:
        require(before[path] == sm['dataset_hashes'][key], f'Standard hash mismatch {key}')
    for key,path in [('standard_rag_result_sha256',fm['inputs']['standard_rag_result']),('standard_rag_manifest_sha256','data/evaluation/generation/standard_rag_manifest_v0.json'),('generation_verified_manifest_sha256','data/evaluation/generation/generation_eval_v1_verified_manifest.json')]:
        require(before[path] == fm['input_hashes'][key], f'Phase 4A hash mismatch {key}')
    require(gm['generation_eval_v1_verified_sha256'] == before[paths['generation_verified_sha256']], 'gold manifest hash mismatch')
    require(gm['source_corpus_sha256'] == before[paths['corpus_chunks_sha256']], 'gold corpus hash mismatch')
    require(gm['source_retrieval_eval_sha256'] == gold_payload['source_retrieval_eval_sha256'] == before[paths['retrieval_eval_sha256']], 'gold retrieval hash mismatch')
    for manifest in [am['manifest'],sm]:
        require(manifest['llm_model'] == 'gemini-3.5-flash-lite', 'model mismatch')
        require(manifest['prompt_version'] == 'legal-rag-prompt-v0', 'prompt mismatch')
        require(manifest['corpus_version'] == 'corpus-v0.1', 'corpus version mismatch')
    require(am['manifest']['retrieval_config'] == CONFIG, 'Agentic config mismatch')
    require(sm['prompt_sha256'] == before['prompts/legal_rag_v0.txt'], 'Standard prompt hash mismatch')
    traces = {}
    trace_paths = []
    for q,row in agentic.items():
        path = Path(row['trace_path'])
        require(path.is_file(), f'missing trace {q}')
        require(path.parent == ROOT/'data/rag/traces/agentic-rag-v1/agentic-v1', 'unexpected trace directory')
        require(path.stem == q, f'trace filename mismatch {q}')
        trace_paths.append(path)
        traces[q] = read(path)
    require(len(set(trace_paths)) == 31, 'trace referenced more than once')
    require(set(trace_paths) == set(trace_paths[0].parent.glob('*.json')), 'missing/extra production trace')
    validate_trace_links(agentic,traces)
    for q,g in gold.items():
        s,a,t,f = standard[q],agentic[q],traces[q],failures[q]
        pids = [p['point_id'] for p in g['required_points']]
        require(len(set(pids)) == len(pids), f'duplicate gold point {q}')
        require(g['annotation_status'] == 'verified', f'unverified query {q}')
        for row in [s,a]:
            require(row['required_point_ids'] == pids, f'required points mismatch {q}')
            for k in ['supported_point_ids','citation_supported_point_ids']:
                require(len(row[k]) == len(set(row[k])) and set(row[k]) <= set(pids), f'point IDs invalid {q}/{k}')
            require(set(row['citation_supported_point_ids']) <= set(row['supported_point_ids']), f'cited support mismatch {q}')
            require(row['generation_error'] is None and row['evaluation_error'] is None, f'benchmark error {q}')
            require(close(row['citation_completeness'],len(row['citation_supported_point_ids'])/len(pids)), f'citation completeness mismatch {q}')
        require(close(a['answer_completeness'],len(a['supported_point_ids'])/len(pids)), f'answer completeness mismatch {q}')
        require(set(s['unsupported_point_ids']) == set(pids)-set(s['supported_point_ids']), f'unsupported IDs mismatch {q}')
        require(close(f['answer_completeness'],len(s['supported_point_ids'])/len(pids)), f'Phase 4A metric mismatch {q}')
        require(f['supported_points'] == s['supported_point_ids'], f'Phase 4A support mismatch {q}')
        for p in g['required_points']:
            fp=point_index[q,p['point_id']]
            require(fp['supporting_chunk_ids'] == p['supporting_chunk_ids'], f'Phase 4A gold support mismatch {q}')
            require((fp['answer_support']=='full') == (p['point_id'] in s['supported_point_ids']), f'Phase 4A point support mismatch {q}')
        for row in [s,t]:
            require(row['model'] == 'gemini-3.5-flash-lite' and row['prompt_version'] == 'legal-rag-prompt-v0', f'per-query model/prompt mismatch {q}')
            require(row['retrieval_config'] == CONFIG, f'per-query retrieval config mismatch {q}')
        require(t['initial_top5'] == s['retrieved_chunk_ids'] == f['top5_chunk_ids'], f'initial evidence mismatch {q}')
        require(t['final_top5'] == [e['chunk_id'] for e in t['final_evidence']], f'final evidence mismatch {q}')
        require(len(set(t['final_top5'])) == len(t['final_top5']) == 5, f'final evidence size mismatch {q}')
        require(t['state']['execution_error'] is None, f'trace execution error {q}')
        for k in ['query','run_id','coverage_check','missing_aspects','sub_queries','draft_answer','completeness_check','citation_check','final_answer','final_status','initial_top5','final_top5','retrieval_calls','llm_calls','expansion_used','revision_used','citation_revision_used']:
            require(t[k] == t['state'][k], f'trace/state disagreement {q}/{k}')
        require(t['expansion_candidates'] == t['state']['expanded_candidates'], f'expanded candidates mismatch {q}')
        require(t['final_evidence'] == t['state']['current_evidence'], f'current evidence mismatch {q}')
        require(a['status'] == t['final_status'], f'status mismatch {q}')
        require(t['budgets'] == BUDGETS, f'budget configuration mismatch {q}')
        n = production_calls(t)
        require(n <= BUDGETS['max_llm_calls'], f'LLM budget violation {q}')
        rc=t['retrieval_calls']; stages=[c['stage'] for c in t['llm_calls']]
        require(len(rc)==t['retrieval_call_count']==1+len(t['sub_queries']), f'retrieval calls mismatch {q}')
        require([c['call_number'] for c in rc] == list(range(1,len(rc)+1)), f'retrieval numbering mismatch {q}')
        require(rc[0]['round']==0 and not rc[0]['sub_query'] and rc[0]['query']==g['query'], f'initial retrieval malformed {q}')
        require([c['query'] for c in rc[1:]]==t['sub_queries'], f'subquery mismatch {q}')
        require(all(c['round']==1 and c['sub_query'] for c in rc[1:]), f'expansion round violation {q}')
        require(len(t['sub_queries'])<=3 and t['state']['retrieval_round']<=1, f'expansion budget violation {q}')
        require(bool(rc[1:])==t['expansion_used'], f'expansion flag mismatch {q}')
        require(t['expansion_used']==(not t['coverage_check']['sufficient'] and bool(t['missing_aspects'])), f'coverage/expansion trigger mismatch {q}')
        require(t['state']['transitions'].count('evidence_merge_rerank')==int(t['expansion_used']), f'evidence merge count mismatch {q}')
        require(t['state']['revision_count']==stages.count('answer_revision')==int(t['revision_used'])<=1, f'answer revision budget/flag mismatch {q}')
        require(t['state']['citation_revision_count']==stages.count('citation_revision')==int(t['citation_revision_used'])<=1, f'citation revision budget/flag mismatch {q}')
        require(stages.count('completeness_check')==1+int(t['revision_used']), f'completeness call mismatch {q}')
        require(stages.count('coverage_check')==stages.count('answer_generation')==1, f'initial check/generation count mismatch {q}')
        require(stages.count('semantic_citation_alignment')==int(t['citation_check']['alignment_checked']), f'semantic call mismatch {q}')
        require(n==3+2*int(t['revision_used'])+int(t['citation_revision_used'])+int(t['citation_check']['alignment_checked']), f'production accounting mismatch {q}')
        require([v for v in t['state']['transitions'] if v in STAGES]==stages, f'transitions/calls mismatch {q}')
        judge=a['judge']; jp={p['point_id']:p for p in judge['points']}
        require(len(jp)==len(judge['points']) and set(jp)==set(pids), f'judge points mismatch {q}')
        require([p for p in pids if jp[p]['supported']]==a['supported_point_ids'], f'judge support mismatch {q}')
        for row,j in [(s,{k:s['judge_'+k] for k in ['claim_count','grounded_claim_count','unsupported_claim_count','cited_claim_count','correctly_cited_claim_count']}),(a,judge)]:
            for metric,num,den in [('citation_correctness','correctly_cited_claim_count','cited_claim_count'),('groundedness','grounded_claim_count','claim_count'),('unsupported_claim_rate','unsupported_claim_count','claim_count')]:
                require(j[den]>0 and close(row[metric],j[num]/j[den]), f'claim metric mismatch {q}/{metric}')
    return {'before':before,'agentic_metrics':am,'standard_manifest':sm,'gold_manifest':gm,'failure_metrics':fm,'gold':gold,'standard':standard,'agentic':agentic,'failures':failures,'point_index':point_index,'traces':traces,'standard_metrics':standard_metrics}

def analyze_query(q, inputs):
    s,a,t,g,f = (inputs[k][q] for k in ['standard','agentic','traces','gold','failures'])
    standard = {m:s.get(m) for m in METRICS}
    standard['answer_completeness']=len(s['supported_point_ids'])/len(s['required_point_ids'])
    deltas=oriented_deltas(standard,a); oc=outcome(deltas)
    p=profile(t['expansion_used'],t['revision_used'],t['citation_revision_used'])
    gained,lost=point_changes(s['supported_point_ids'],a['supported_point_ids'])
    added,removed=point_changes(t['initial_top5'],t['final_top5'])
    gold_chunks={c for point in g['required_points'] for c in point['supporting_chunk_ids']}
    draft=t['draft_answer']; final=t['final_answer']
    row={'query_id':q,'query':g['query'],'trace_path':str(Path(a['trace_path']).relative_to(ROOT)),'required_point_ids':a['required_point_ids'],'required_point_count':len(a['required_point_ids'])}
    for m in METRICS:
        row['standard_'+m]=standard[m]; row['agentic_'+m]=a[m]
        row['unsupported_claim_improvement' if m=='unsupported_claim_rate' else 'delta_'+m]=deltas[m]
    row.update({'oriented_metric_deltas':deltas,'standard_supported_point_ids':s['supported_point_ids'],'agentic_supported_point_ids':a['supported_point_ids'],'gained_supported_point_ids':gained,'lost_supported_point_ids':lost,'interventions':{'evidence_expansion':t['expansion_used'],'answer_revision':t['revision_used'],'citation_revision':t['citation_revision_used']},'primary_intervention_profile':PROFILES[p],'profile_key':p,'quality_outcome':OUTCOMES[oc],'outcome_key':oc,'coverage_check':t['coverage_check'],'missing_aspects':t['missing_aspects'],'subqueries':t['sub_queries'],'subquery_count':len(t['sub_queries']),'expanded_candidate_chunk_ids':t['expansion_candidates'],'initial_top5_chunk_ids':t['initial_top5'],'final_top5_chunk_ids':t['final_top5'],'added_final_evidence_chunk_ids':added,'removed_initial_evidence_chunk_ids':removed,'final_top5_order_changed':t['initial_top5']!=t['final_top5'],'final_top5_membership_changed':bool(added or removed),'gold_supporting_chunks_added_by_expansion':sorted(set(added)&gold_chunks),'gold_supporting_chunks_removed_by_expansion':sorted(set(removed)&gold_chunks),'gold_overlap_interpretation':'post-hoc gold-support overlap; not semantic sufficiency','initial_gold_support_overlap':sorted(set(t['initial_top5'])&gold_chunks),'final_gold_support_overlap':sorted(set(t['final_top5'])&gold_chunks),'expansion_observation':OBSERVATIONS[oc] if t['expansion_used'] else None,'attribution_note':'multiple interventions — attribution not isolated' if p=='multiple' else 'single intervention; observational association only' if p!='none' else 'No Substantive Intervention; generation/evaluator variability remains possible','retrieval_calls':len(t['retrieval_calls']),'production_llm_calls':production_calls(t),'production_llm_stages':[c['stage'] for c in t['llm_calls']],'retrieval_call_details':[{k:c[k] for k in ['call_number','round','query','sub_query','candidate_count','candidate_chunk_ids','top5_chunk_ids']} for c in t['retrieval_calls']],'execution_path_raw':t['state']['transitions'],'final_status':t['final_status'],'budgets':t['budgets'],'budget_compliance':'PASS','standard_failure_profile':{k:f[k] for k in ['primary_failure_counts','overall_root_cause','query_taxonomy','has_retrieval_miss','has_evidence_coverage_issue','has_generation_issue','has_citation_issue']},'standard_answer':s['answer'],'draft_answer':draft,'final_answer':final,'draft_to_final_answer_changed':draft!=final,'draft_to_final_non_citation_text_changed':lexical_body(draft)!=lexical_body(final),'standard_to_agentic_answer_changed':s['answer']!=final,'draft_citation_ids':citations(draft),'final_citation_ids':citations(final),'draft_to_final_citation_ids_changed':set(citations(draft))!=set(citations(final)),'draft_equals_standard_answer':draft==s['answer'],'draft_evidence_equals_standard_content_and_citation_map':evidence_signature(t['final_evidence'])==evidence_signature(s['evidence']),'deterministic_citation_check':t['citation_check'],'semantic_citation_check_used':t['citation_check']['alignment_checked'],'frozen_agentic_judge':a['judge'],'direct_revision_benchmark_effect_confirmed':False})
    if t['revision_used']:
        row['initial_completeness_check']={'complete':None,'missing_points':None,'reason':None,'availability':'not_retained; final check overwrites initial check','inferred_trigger_complete':False,'inference_basis':'answer_revision transition and read-only controller branch inspection'}
    else:
        row['initial_completeness_check']={**t['completeness_check'],'availability':'retained; the sole completeness check'}
    row['final_completeness_check']={**t['completeness_check'],'scope':'last internal completeness decision; before Citation Revision' if t['citation_revision_used'] else 'final answer','recheck_used':t['revision_used']}
    row['initial_to_final_evidence_content_and_citation_map_unchanged']=evidence_signature(t['state']['initial_evidence'])==evidence_signature(t['final_evidence'])
    row['standard_final_cited_chunk_ids']=sorted(e['chunk_id'] for e in s['evidence'] if e['evidence_id'] in s['cited_evidence_ids'])
    row['agentic_final_cited_chunk_ids']=sorted(e['chunk_id'] for e in t['final_evidence'] if e['evidence_id'] in t['citation_check']['cited_evidence_ids'])
    row['standard_to_agentic_cited_chunks_changed']=row['standard_final_cited_chunk_ids']!=row['agentic_final_cited_chunk_ids']
    row['citation_revision_observation']={'used':t['citation_revision_used'],'pre_revision_answer':None if t['citation_revision_used'] else 'not_applicable','pre_validator_status':None,'pre_validator_failure_inferred':t['citation_revision_used'],'pre_validator_issue_details':None,'final_validator_valid':t['citation_check']['valid'],'validator_fix':'trace-consistent inferred failure-to-pass; exact failure not retained' if t['citation_revision_used'] else 'not_applicable','substantive_content_change_during_citation_revision':'not_identifiable: post-Answer-Revision/pre-Citation-Revision answer not retained' if t['citation_revision_used'] else 'not_applicable','benchmark_association':OBSERVATIONS[oc] if t['citation_revision_used'] else None}
    row['rescue_type']='fully_rescued' if standard['answer_completeness']<1-EPS and close(a['answer_completeness'],1) else 'partially_rescued' if deltas['answer_completeness']>EPS and a['answer_completeness']<1-EPS else None
    row['regressions']=[{'metric':m,'standard':standard[m],'agentic':a[m],'oriented_delta':v} for m,v in deltas.items() if v is not None and v < -EPS]
    row['self_check_calibration'],row['success_status_but_benchmark_incomplete']=calibrate(t['completeness_check']['complete'],a['answer_completeness'],t['final_status'])
